  'This course teaches students to design, execute, measure, and govern social media marketing programs across platform ecosystems. It balances strategy, audience insight, content creation, community management, creator partnerships, paid social, analytics, ethics, and crisis readiness.',
  $smmkjson${"slug": "social-media-marketing", "title": "Social Media Marketing", "description": "This course teaches students to design, execute, measure, and govern social media marketing programs across platform ecosystems. It balances strategy, audience insight, content creation, community management, creator partnerships, paid social, analytics, ethics, and crisis readiness.", "topics": [{"id": "562f2cb0-b46a-44eb-a02b-88fa42b6ef8f", "type": "topic", "title": "Social Media Marketing Strategy and Platform Ecosystem", "description": "Students begin by treating social media as a strategic marketing system, not a posting calendar. The unit connects business objectives, audiences, platforms, brand voice, content, community, paid media, and measurement.", "children": [{"id": "39601a49-de6a-4522-b4fa-2605c1b6b8b6", "type": "subtopic", "title": "Strategic role of social media", "children": [{"id": "02861492-a36a-4b87-934e-377d40de627c", "type": "concept", "title": "Awareness, consideration, conversion, retention, service, advocacy, and reputation"}, {"id": "a76e3537-6135-4a9f-84cd-a990d5f74762", "type": "concept", "title": "Paid, owned, earned, and shared media integration"}, {"id": "092a0e59-2c0a-4d14-9a83-6b8c90937c80", "type": "concept", "title": "Social media as channel, community, marketplace, and feedback system"}], "description": "Students learn where social belongs in the marketing mix and what it can and cannot accomplish for a brand."}, {"id": "63694dd4-194d-414d-8882-8ac9759be9dc", "type": "subtopic", "title": "Platform ecosystem and business models", "children": [{"id": "b8cd7acd-51f6-46e5-83d1-c0848944491c", "type": "concept", "title": "Feed, search, short-video, messaging, livestream, community, and professional platforms"}, {"id": "ca9e66fd-e8e8-4872-8f3d-345509c15f9a", "type": "concept", "title": "Algorithmic ranking, ad auctions, creators, subscriptions, and commerce features"}, {"id": "60fb6ecb-f27b-47af-952e-77de46ee88a7", "type": "concept", "title": "Platform dependence, policy change, measurement loss, and channel diversification"}], "description": "This subtopic shows how platform incentives shape visibility, content formats, advertising products, and brand behavior."}, {"id": "227659e0-541f-40b6-ae20-27af48d94cb1", "type": "subtopic", "title": "Strategy brief and objective setting", "children": [{"id": "5ac548c2-38e2-45cc-b047-afbdff42dcad", "type": "concept", "title": "SMART objectives, target audiences, positioning, message priorities, and budget logic"}, {"id": "06a0e1d5-ac8d-4f32-a580-dbaa09f085fb", "type": "concept", "title": "Funnel, journey, community, and brand-equity objectives"}, {"id": "cd5c6bc9-8a70-4912-8ab1-1997ad459aee", "type": "concept", "title": "Scope, assumptions, constraints, governance, and approval processes"}], "description": "Students practice turning brand and business goals into a coherent social strategy."}]}, {"id": "829b892e-cb89-4746-9623-242114e73ec6", "type": "topic", "title": "Audience Research, Personas, and Social Listening", "description": "This section teaches students to understand audiences through research, platform behavior, social listening, communities, and cultural context before creating content or buying media.", "children": [{"id": "4296611e-4ced-491d-afa6-35d5e8fb1f57", "type": "subtopic", "title": "Audience insight methods", "children": [{"id": "d20eb431-2e38-49a4-a799-f541eb13b40a", "type": "concept", "title": "Surveys, interviews, focus groups, platform insights, CRM, search, and social listening"}, {"id": "e5ac3b34-94ff-4217-ab60-b11af14b21e0", "type": "concept", "title": "Demographics, psychographics, needs, jobs-to-be-done, and cultural context"}, {"id": "c05afcf8-8927-41e9-a979-06c82b03d240", "type": "concept", "title": "Research bias, representativeness, and responsible interpretation"}], "description": "Students combine research methods with social data to understand who the campaign is for and what they care about."}, {"id": "9771bd6e-1b60-4aef-8ad9-888346a22140", "type": "subtopic", "title": "Personas and community mapping", "children": [{"id": "88b4bb53-b9fe-49d6-afef-ed84a7f690e2", "type": "concept", "title": "Audience segments, personas, communities, subcultures, and networked publics"}, {"id": "49d0202b-8184-4846-bb57-5cb0e7ad85d8", "type": "concept", "title": "Motivations, barriers, media habits, content preferences, and social norms"}, {"id": "fef8f0ce-1063-4aca-bb94-38fccf750d5e", "type": "concept", "title": "Influencers, gatekeepers, advocates, skeptics, and peer-to-peer influence"}], "description": "Students learn to build personas and community maps that guide content and engagement decisions."}, {"id": "e0b6df91-e22f-4ed5-9a3d-c06744141697", "type": "subtopic", "title": "Listening and sentiment analysis", "children": [{"id": "1920f103-dd10-412a-98ef-31314c34e2fb", "type": "concept", "title": "Keywords, topics, hashtags, mentions, share of voice, and competitive monitoring"}, {"id": "e13f59ed-03b3-4ca9-987c-b84c9802d40f", "type": "concept", "title": "Sentiment, emotion, intent, sarcasm, context, and language limitations"}, {"id": "0abc9362-d836-4860-964d-d5dd8d2c6a05", "type": "concept", "title": "Issue detection, trend spotting, insight synthesis, and escalation triggers"}], "description": "Students learn how to use social listening to identify conversations, needs, risks, and opportunities."}]}, {"id": "bb852561-d889-40ad-b8d6-8e9fd5f4d377", "type": "topic", "title": "Platform Strategies and Affordances", "description": "Students compare major platforms by affordances, algorithms, audience expectations, ad products, creator norms, and brand risks. The goal is to choose channels because they fit the strategy.", "children": [{"id": "dc43e154-025c-402a-8f9a-f445a2893b94", "type": "subtopic", "title": "Platform-specific strategy", "children": [{"id": "f3858c07-fbfb-496d-a0ed-94c808f47c82", "type": "concept", "title": "Instagram, TikTok, YouTube, LinkedIn, Facebook, Reddit, Pinterest, Snapchat, and X"}, {"id": "57ce647b-1efb-45a3-b155-121c4f83164a", "type": "concept", "title": "B2B, B2C, community, creator, education, entertainment, search, and commerce use cases"}, {"id": "0f11bdd4-d7fe-4f87-a6e7-29c86216c74f", "type": "concept", "title": "Platform fit, opportunity cost, brand risk, and resource requirements"}], "description": "Students compare platforms by audience, format, culture, and business purpose instead of treating social as one generic channel."}, {"id": "8eb433b3-7d7e-4296-bce8-325f822daa1b", "type": "subtopic", "title": "Affordances and native behavior", "children": [{"id": "a3b2eeec-b27f-48e3-b4fe-a4081e2007df", "type": "concept", "title": "Video, images, stories, livestreams, carousels, threads, groups, comments, DMs, and polls"}, {"id": "57bc727f-974a-445a-9bc9-8a9146b50e8a", "type": "concept", "title": "Discoverability, algorithmic feeds, search, hashtags, recommendations, and social graphs"}, {"id": "00f5b1b0-c007-400e-9bda-b5693d6b574b", "type": "concept", "title": "Native creative conventions, pacing, captions, sound, thumbnails, and hooks"}], "description": "Platform affordances shape how people create, discover, react, and share content."}, {"id": "ca377e3b-ba35-4b54-b7fa-7a9e6eed24c0", "type": "subtopic", "title": "Channel portfolio governance", "children": [{"id": "226f45e6-5559-4d20-a77b-fa31832a5af7", "type": "concept", "title": "Primary, secondary, experimental, and dormant channel roles"}, {"id": "e56a3582-910e-452e-9844-7dd5c6c634c3", "type": "concept", "title": "Channel launch, maintenance, sunset, and escalation criteria"}, {"id": "d6d825df-59a7-4e1f-bb2b-ed6a7f8d1298", "type": "concept", "title": "Ownership, publishing rights, passwords, brand consistency, and platform audits"}], "description": "Students learn to manage multiple channels as a coordinated portfolio."}]}, {"id": "01ac6caa-89fa-4085-8409-be78df1e0a24", "type": "topic", "title": "Content Strategy, Editorial Planning, and Brand Voice", "description": "This topic turns positioning into repeatable social content systems: pillars, calendars, formats, copy, creative briefs, and governance.", "children": [{"id": "be17b590-2a19-415c-aade-31572008974f", "type": "subtopic", "title": "Content pillars and message architecture", "children": [{"id": "e12cfb4a-6cde-4b55-8ba4-5120230aa86f", "type": "concept", "title": "Content pillars, campaign themes, proof points, calls to action, and story arcs"}, {"id": "1ae19202-22fd-4d48-8e6b-0733d8274ab6", "type": "concept", "title": "Educational, entertaining, inspirational, promotional, community, and service content"}, {"id": "4d3a591f-6747-40b8-9492-d699fa730215", "type": "concept", "title": "Balancing brand consistency with platform-native adaptation"}], "description": "Students learn to create a repeatable system for what the brand says and why it matters."}, {"id": "ee5c2232-e8e1-430f-9b7d-ee07044701b0", "type": "subtopic", "title": "Editorial calendars and workflow", "children": [{"id": "52028fd7-7d72-4bfa-9e26-eb181da7524b", "type": "concept", "title": "Monthly, weekly, and daily calendars; tentpoles; launches; and recurring series"}, {"id": "e20f2018-19b1-40bf-9855-6064a799bbaf", "type": "concept", "title": "Briefing, drafting, design, legal review, approval, scheduling, and publishing"}, {"id": "569e0500-9f28-4dc1-8ab6-acb20ad340ec", "type": "concept", "title": "Real-time opportunities, trend participation, and guardrails"}], "description": "Strong social media programs depend on planning systems that can still adapt to cultural moments."}, {"id": "c0c60652-780c-422f-9bb6-e73f05f04aba", "type": "subtopic", "title": "Brand voice and copywriting", "children": [{"id": "8f656911-933d-4be5-b2be-b509e1c026af", "type": "concept", "title": "Voice, tone, style, captions, hooks, hashtags, accessibility text, and CTAs"}, {"id": "05732c94-d2bb-453c-a9c5-6c4bf83878ea", "type": "concept", "title": "Writing for skimming, mobile, comments, shares, and saves"}, {"id": "129ce10f-a4b8-4416-81d5-7ae08a067dad", "type": "concept", "title": "Humor, sincerity, controversy, cultural references, and brand safety"}], "description": "Students practice writing social copy that is clear, useful, human, and aligned with the brand."}]}, {"id": "99f760fc-208d-4e48-8fcb-39f39d612372", "type": "topic", "title": "Short-Form Video, Visual Storytelling, and Production Workflow", "description": "Students learn why video-led social works, how to design platform-native creative, and how to manage a lean content production workflow.", "children": [{"id": "006c6079-144a-4aa9-80ce-4a26bafc3733", "type": "subtopic", "title": "Video-first creative strategy", "children": [{"id": "abf22c3a-75be-4e9e-8830-c0a083806e8c", "type": "concept", "title": "Hooks, pacing, pattern interrupts, captions, sound, thumbnails, and loops"}, {"id": "3a38dfe4-59a3-49bf-9f7e-a691a2376637", "type": "concept", "title": "Educational, behind-the-scenes, testimonial, product, creator, and narrative formats"}, {"id": "2300cbaa-e89a-4dbc-9c8a-02b9ce602ba0", "type": "concept", "title": "Retention curves, completion rate, rewatches, shares, and saves"}], "description": "Students learn why short-form video dominates many platforms and how to design creative for attention and retention."}, {"id": "2c688ec9-6288-4102-9321-c170854c0b41", "type": "subtopic", "title": "Lean production systems", "children": [{"id": "b3880389-ad96-4202-a49c-9f5e7a66cb95", "type": "concept", "title": "Creative briefs, shot lists, scripting, filming, editing, versioning, and asset libraries"}, {"id": "31ddeec6-5619-41cb-8fc5-3c6e6ef2e92d", "type": "concept", "title": "Batch production, repurposing, templates, UGC-style creative, and brand kits"}, {"id": "7530b2da-dc75-4049-a60d-12712730e093", "type": "concept", "title": "Legal, music rights, talent releases, accessibility, and quality control"}], "description": "Students learn how teams produce high-volume creative without losing quality or strategy."}, {"id": "52901eab-7469-4068-99cd-ecedcaae150c", "type": "subtopic", "title": "Visual identity in social contexts", "children": [{"id": "f7b16cc6-0129-4fd6-9d18-6632bc6f6ce0", "type": "concept", "title": "Brand systems, typography, color, motion, composition, and product framing"}, {"id": "1afc97d9-1b73-472b-a99e-5090d71d6563", "type": "concept", "title": "Templates, creator-style content, memes, screenshots, and lo-fi authenticity"}, {"id": "97afb84f-ea33-458b-acbe-4c6edbb849cd", "type": "concept", "title": "Accessibility, contrast, captions, alt text, and inclusive imagery"}], "description": "Social visuals must be recognizable while still feeling native to each platform."}]}, {"id": "2ad4aade-ea36-4b19-bc75-eae5be7fcd43", "type": "topic", "title": "Community Management, Engagement, and Social Care", "description": "Social media marketing is relational. Students learn how brands listen, respond, moderate, support customers, build trust, and manage community norms.", "children": [{"id": "876e2c9a-3ea7-476f-96ad-dca25d447b53", "type": "subtopic", "title": "Community strategy", "children": [{"id": "f2701f48-2ea5-4842-89a6-35434f19080d", "type": "concept", "title": "Community purpose, member roles, norms, rituals, and engagement loops"}, {"id": "732e38ce-33bb-4872-a8a2-6480db81a032", "type": "concept", "title": "Comments, DMs, groups, forums, user-generated content, and advocacy"}, {"id": "3f13d1c4-d8cd-4093-a124-a5ed656c5b57", "type": "concept", "title": "Participation ladders, superusers, ambassadors, and community health"}], "description": "Students learn how brands build communities through participation, recognition, moderation, and value exchange."}, {"id": "38cc6ad7-11d0-4bb7-ae24-aaf91ece0778", "type": "subtopic", "title": "Response and moderation", "children": [{"id": "aee0fd34-128d-4b3d-8c76-19a9d10e5e8d", "type": "concept", "title": "Response matrices, tone guidelines, FAQs, triage, handoffs, and service levels"}, {"id": "ffd96e38-b74c-4128-babe-56253bc8cee5", "type": "concept", "title": "Moderation rules, harassment, spam, misinformation, and harmful content"}, {"id": "1df61075-48d6-410c-ac25-a0e7efecf35a", "type": "concept", "title": "Documentation, screenshots, issue logs, and escalation paths"}], "description": "Community management requires speed, judgment, empathy, and escalation discipline."}, {"id": "bbec0705-2708-421e-99e6-aae88ae8cc51", "type": "subtopic", "title": "Social care and customer experience", "children": [{"id": "a9241cf2-cf99-4d6a-aaf7-e8afe89a0fad", "type": "concept", "title": "Customer complaints, product questions, refunds, service recovery, and public apologies"}, {"id": "1148a882-c31c-4b93-8127-7e8ff5f198c7", "type": "concept", "title": "CRM integration, case routing, sentiment history, and customer privacy"}, {"id": "64894d1c-6c5b-405c-b507-c5ccda54dd96", "type": "concept", "title": "Turning recurring issues into product, operations, or content insights"}], "description": "Social channels often become service channels, whether marketers plan for it or not."}]}, {"id": "fe2079c3-0513-426a-a953-9186cd993284", "type": "topic", "title": "Influencer, Creator, Affiliate, and Partnership Strategy", "description": "This unit treats creators as strategic partners with audiences, credibility, formats, contracts, and measurement needs. Students learn to design ethical and effective collaborations.", "children": [{"id": "11f6fa65-3ee0-48ca-9a4e-a1ce04a9450e", "type": "subtopic", "title": "Creator landscape and selection", "children": [{"id": "30b939ca-252d-4975-b624-4d48ba9083d1", "type": "concept", "title": "Mega, macro, mid-tier, micro, nano, employee, expert, and community creators"}, {"id": "74432884-a615-41e9-aed7-22b2664dfbb6", "type": "concept", "title": "Audience fit, credibility, engagement quality, content style, brand safety, and cost"}, {"id": "d44f2d06-8ed7-4c84-b009-e031ef26ab4c", "type": "concept", "title": "Creator discovery, vetting, shortlisting, and outreach"}], "description": "Students learn to choose creators based on strategic fit, not follower count alone."}, {"id": "4a21a5ec-b250-4f55-8502-b861a2e5afce", "type": "subtopic", "title": "Partnership design and contracts", "children": [{"id": "61a5a6cb-4dcf-4f96-b5c2-c7886c807888", "type": "concept", "title": "Briefs, deliverables, usage rights, whitelisting, exclusivity, approvals, and payment"}, {"id": "a07f49bd-8d02-4013-820c-fbe54f9bfd80", "type": "concept", "title": "FTC disclosure, authenticity, creative freedom, and brand guidelines"}, {"id": "4b7607f9-861f-4a6e-a30e-85244562dd8a", "type": "concept", "title": "Affiliate codes, UTM links, tracking, contracts, and creator relations"}], "description": "Good partnerships clarify value, deliverables, rights, disclosure, timing, and measurement."}, {"id": "d42f4676-1642-47ad-99f3-af0fe784b6c7", "type": "subtopic", "title": "Creator performance and learning", "children": [{"id": "bee65929-02d1-4354-8cf9-7665ada227b2", "type": "concept", "title": "Reach, engagement, saves, clicks, conversions, revenue, sentiment, and content reuse"}, {"id": "25bf7bee-091f-4515-84fc-ff882395789b", "type": "concept", "title": "Incrementality, creator lift, audience quality, and long-term brand effects"}, {"id": "2e58aefb-2253-4c8f-b04c-db3bcf56da4c", "type": "concept", "title": "Post-campaign learning, creator scorecards, and relationship portfolios"}], "description": "Students evaluate creator campaigns beyond surface engagement."}]}, {"id": "7c79c071-e82a-4e20-9289-08f7b8d23e5a", "type": "topic", "title": "Paid Social Advertising and Media Planning", "description": "Students learn how paid social translates audience, creative, budget, bidding, targeting, and testing into measurable campaign performance.", "children": [{"id": "15bd4e8d-a6a8-4bbd-a184-6e8e6893268a", "type": "subtopic", "title": "Paid social fundamentals", "children": [{"id": "762db67b-cc19-45e4-bcd1-c7dbaf8bdbd5", "type": "concept", "title": "Campaign objectives, ad sets, creatives, placements, bids, budgets, and optimization events"}, {"id": "631732df-4476-4ec2-bc9a-0a1c792e03e8", "type": "concept", "title": "Reach, traffic, engagement, leads, app installs, sales, and awareness objectives"}, {"id": "beb3dfb0-b2b6-4f25-8577-999d62fe077f", "type": "concept", "title": "Learning phase, frequency, fatigue, pacing, and budget allocation"}], "description": "Students learn how ad platforms turn objectives, audiences, creative, bids, and budgets into delivery."}, {"id": "319defb3-b184-4516-a798-01d9d2a87e01", "type": "subtopic", "title": "Targeting and creative testing", "children": [{"id": "d2247f84-bc3b-48b6-a1e2-b2ca1eb9bde5", "type": "concept", "title": "Custom, lookalike, interest, demographic, contextual, retargeting, and broad audiences"}, {"id": "9ad0e246-e3ce-496f-abb0-31991918d072", "type": "concept", "title": "Creative hypotheses, ad variants, landing pages, offers, and CTAs"}, {"id": "e0d25802-7d16-434b-ad62-67909e2748ed", "type": "concept", "title": "Testing structure, holdouts, statistical discipline, and decision rules"}], "description": "Paid social performance depends on audience design and creative variation."}, {"id": "6ada15cc-3a3d-4a5b-bfd4-854365285fe9", "type": "subtopic", "title": "Media planning and reporting", "children": [{"id": "efd362da-3671-473e-83a1-2304eb520bf0", "type": "concept", "title": "CPM, CPC, CTR, CVR, CPA, ROAS, CAC, LTV, and contribution margin"}, {"id": "c1bfe8c0-df13-4a8f-9e95-5dfe1a19cb7b", "type": "concept", "title": "Campaign pacing, budget reallocation, attribution windows, and platform discrepancies"}, {"id": "a374ab9b-38c8-44e6-a0ec-4df0a82b803c", "type": "concept", "title": "Media plan rationale, optimization notes, and executive reporting"}], "description": "Students learn to connect paid social performance to a wider media and business plan."}]}, {"id": "d63fe1bd-aa6a-4400-b349-014587c28a00", "type": "topic", "title": "Social Commerce, CRM, and Customer Journey Integration", "description": "This topic connects social touchpoints to ecommerce, lead generation, CRM, loyalty, service, and the broader customer journey.", "children": [{"id": "20c670e0-c632-4b58-8eda-029349e0b57a", "type": "subtopic", "title": "Social commerce mechanics", "children": [{"id": "eb7513bc-4cf4-4b0f-880e-8fd889b8944d", "type": "concept", "title": "Shoppable posts, product catalogs, livestream commerce, storefronts, and affiliate links"}, {"id": "6161105f-302e-4d9e-a9c6-95f74b1de6b7", "type": "concept", "title": "Discovery, consideration, social proof, urgency, and purchase friction"}, {"id": "630c2bef-7751-4304-9f8b-af8d81992df1", "type": "concept", "title": "Commerce metrics, feed quality, merchandising, and conversion paths"}], "description": "Students study how social platforms increasingly support product discovery, checkout, reviews, livestream shopping, and creator-driven commerce."}, {"id": "4818c10f-0d57-4499-b97e-55648fd3d13c", "type": "subtopic", "title": "CRM and lifecycle integration", "children": [{"id": "9f317330-b8d4-4544-925f-ff88563b953f", "type": "concept", "title": "Lead generation, email capture, CRM enrichment, retargeting, and loyalty programs"}, {"id": "5965c195-01f3-4426-9ee8-94f6e2f84aa5", "type": "concept", "title": "Lifecycle stages, onboarding, retention, reactivation, referral, and advocacy"}, {"id": "b922b789-e622-4dc3-8298-66c51e1cb3c2", "type": "concept", "title": "Consent, data matching, suppression lists, and cross-channel orchestration"}], "description": "Social media becomes more powerful when connected to customer data and lifecycle strategy."}, {"id": "04e68c95-5376-4897-8d1b-924e92032d6e", "type": "subtopic", "title": "Journey and touchpoint design", "children": [{"id": "ad0347d0-0925-4011-99cf-f55b8628bdfd", "type": "concept", "title": "Awareness, consideration, conversion, onboarding, support, loyalty, and advocacy"}, {"id": "f324e235-df48-46e0-8a41-932b432aa1d5", "type": "concept", "title": "Touchpoint sequencing, content needs, friction, and micro-conversions"}, {"id": "0cbcd93d-32c8-40f4-8578-d838e03ed3e8", "type": "concept", "title": "Omnichannel coordination with search, email, web, retail, events, and sales"}], "description": "Students map social's role across the full customer journey."}]}, {"id": "0c77d85f-c8d1-4edf-84c6-ed070560fec5", "type": "topic", "title": "Analytics, KPIs, Attribution, and Dashboards", "description": "Students learn to measure social performance with metrics that match objectives, while understanding attribution limits and platform-reporting bias.", "children": [{"id": "85841d23-8e80-44d9-bcb9-3c0aacbabd75", "type": "subtopic", "title": "Objective-led metrics", "children": [{"id": "3c85e008-5ab6-41f1-8f93-3ed1646b90a2", "type": "concept", "title": "Awareness, reach, impressions, frequency, engagement, watch time, clicks, leads, sales, retention, and sentiment"}, {"id": "5c0777b4-dbd6-4789-bc37-639420522e60", "type": "concept", "title": "Input, output, diagnostic, guardrail, and business-impact metrics"}, {"id": "365f38f7-0132-497b-935d-793939fcad1c", "type": "concept", "title": "Avoiding vanity metrics and metric overload"}], "description": "Students learn to select metrics based on what the campaign is supposed to accomplish."}, {"id": "08a2c7fc-f222-4664-b0e6-d017bcb56a49", "type": "subtopic", "title": "Attribution and measurement limits", "children": [{"id": "534011f7-dc64-488e-939e-6d9c944d771b", "type": "concept", "title": "UTMs, pixels, conversion APIs, attribution windows, view-through, click-through, and dark social"}, {"id": "d9b38d09-a117-492b-a67d-f83c6fc05a8e", "type": "concept", "title": "Incrementality, lift, holdouts, MMM, and platform self-attribution"}, {"id": "68bed577-b093-4d96-b29c-54f07cae009d", "type": "concept", "title": "Measurement loss from privacy changes, blockers, cross-device behavior, and consent gaps"}], "description": "Students learn why platform numbers differ and why attribution is not the same as causation."}, {"id": "aac5f080-33b8-496e-a3d7-c5d258ef3f5f", "type": "subtopic", "title": "Dashboard and insight design", "children": [{"id": "34b80da6-4408-4a2e-a89a-ac6b11ebc5b2", "type": "concept", "title": "Channel dashboards, campaign dashboards, executive scorecards, and creative scorecards"}, {"id": "4c7bb416-33be-4292-9fd8-4e1bafaf3290", "type": "concept", "title": "Benchmarks, targets, annotations, cohort views, and trend lines"}, {"id": "524445bb-f3e7-4efe-80e6-834194880df2", "type": "concept", "title": "Insight writing, recommendations, caveats, and next actions"}], "description": "Dashboards should support decisions, not just summarize activity."}]}, {"id": "dfe14310-8d32-42c7-ae7c-a93f1cc19e99", "type": "topic", "title": "Experimentation, Optimization, and Growth Loops", "description": "This section teaches students to improve social programs through structured testing, creative iteration, conversion optimization, and learning loops.", "children": [{"id": "e2425ed8-9c31-4006-a42d-240dffaa0a2b", "type": "subtopic", "title": "Creative and content testing", "children": [{"id": "a4f57774-aa81-49c8-941c-0186ee35bd3c", "type": "concept", "title": "A/B tests, multivariate tests, sequential tests, and creative rotation"}, {"id": "3362ad38-88d6-4ecc-a2de-2b1718f865b2", "type": "concept", "title": "Hypotheses, sample size, test duration, success metrics, and guardrails"}, {"id": "c7ecffd8-0e6f-478e-9280-7b34a8de4cc0", "type": "concept", "title": "Winning creative, learning agendas, and creative fatigue"}], "description": "Students learn how to test hooks, formats, messages, thumbnails, offers, and CTAs without mistaking noise for insight."}, {"id": "e15b3511-5546-4254-aec5-50adff2a297e", "type": "subtopic", "title": "Conversion optimization", "children": [{"id": "ad46a61a-a23a-4534-a673-241412c0b8b0", "type": "concept", "title": "Landing page message match, page speed, form friction, mobile UX, and trust cues"}, {"id": "adc798d8-db38-4c57-be3b-9573c6b389d2", "type": "concept", "title": "Lead quality, conversion rate, funnel drop-off, and checkout behavior"}, {"id": "2b242a71-f5b9-451b-8118-3cfd7cc73c74", "type": "concept", "title": "Retargeting, abandoned carts, nurture flows, and offer testing"}], "description": "Social campaigns often fail after the click. Students evaluate landing pages, forms, product pages, and app flows."}, {"id": "89ee9138-0ebd-41ac-855d-509c09d5880c", "type": "subtopic", "title": "Growth loops and learning systems", "children": [{"id": "90fe2b68-a61d-4df7-88a0-5bced2a5f866", "type": "concept", "title": "Content loops, referral loops, community loops, creator loops, and product-led loops"}, {"id": "d80aeca6-98a5-43de-9e07-b274c08b3e7b", "type": "concept", "title": "Postmortems, test logs, insight repositories, and playbook updates"}, {"id": "896b0be3-3471-4842-b21f-1c5b86091078", "type": "concept", "title": "Scaling what works while protecting brand quality and customer trust"}], "description": "The best social programs turn each campaign into better future performance."}]}, {"id": "ca9cd56c-27bf-4855-95da-3a8ea0c031cf", "type": "topic", "title": "Brand Safety, Reputation, Crisis, and Issues Management", "description": "Social platforms can amplify risk quickly. Students learn how to prepare for criticism, misinformation, escalation, crises, and reputation repair.", "children": [{"id": "8f3aa4cc-8cad-419d-adfe-81f1c1888bd6", "type": "subtopic", "title": "Risk monitoring and early warning", "children": [{"id": "a73e0e49-9e1a-463b-a1f0-3253c365ef8d", "type": "concept", "title": "Social listening alerts, sentiment spikes, keywords, rumor tracking, and stakeholder monitoring"}, {"id": "1af60194-15f5-45c7-ae37-a5fd0cf876c3", "type": "concept", "title": "Brand safety, misinformation, impersonation, fake accounts, and cultural risk"}, {"id": "3f4ba008-fa80-493f-b747-de454c02942c", "type": "concept", "title": "Vulnerability audits, risk registers, and escalation thresholds"}], "description": "Students learn to detect issues before they become crises."}, {"id": "c45b9118-eb75-4cd9-966c-456814dce67f", "type": "subtopic", "title": "Crisis response on social platforms", "children": [{"id": "fe96b779-6c5f-4fab-aae1-3594ccc75623", "type": "concept", "title": "Holding statements, message maps, Q&A, apology, accountability, and correction"}, {"id": "615054c3-3e55-448d-8d78-ff842915fb0f", "type": "concept", "title": "Escalation teams, legal review, spokesperson alignment, and internal coordination"}, {"id": "5e3c1cf8-25f5-4b00-8cc1-992ba8b17680", "type": "concept", "title": "Platform-specific response choices: pin, reply, hide, delete, DM, pause, or escalate"}], "description": "This subtopic prepares students to respond under speed, ambiguity, and public pressure."}, {"id": "a8b763d4-c336-40e4-80f8-e498bce43f2f", "type": "subtopic", "title": "Reputation recovery and learning", "children": [{"id": "831e7204-59ab-4caf-8b73-157fc8a47395", "type": "concept", "title": "After-action reviews, stakeholder care, restitution, transparency, and ongoing updates"}, {"id": "6fb1d93e-8ef2-40a3-ae30-94f2ac5b40db", "type": "concept", "title": "Brand recovery metrics, sentiment, share of voice, and trust indicators"}, {"id": "895e24dc-14ce-451e-99e5-8ac8f195f3b7", "type": "concept", "title": "Policy changes, employee communication, and future prevention"}], "description": "Students study how brands rebuild trust after criticism or failure."}]}, {"id": "dede7282-7788-46cf-b679-74d7c69ef1fb", "type": "topic", "title": "Ethics, Privacy, Accessibility, Inclusion, and Platform Governance", "description": "This section treats responsible social marketing as a core professional skill: privacy, consent, inclusion, accessibility, bias, disclosure, and platform power shape every campaign.", "children": [{"id": "07521c5f-9f9c-4b7f-9f92-b821b6409807", "type": "subtopic", "title": "Privacy, consent, and data ethics", "children": [{"id": "180c5eff-f126-4c8b-a568-17572da9d542", "type": "concept", "title": "Consent, data minimization, retention, purpose limitation, and user rights"}, {"id": "90dfbf3f-0253-49be-8b6f-cc80493f1693", "type": "concept", "title": "Tracking pixels, conversion APIs, custom audiences, lookalikes, and data sharing"}, {"id": "5ee3b0fe-62ca-48e2-86f7-68c675b35034", "type": "concept", "title": "FTC guidance, platform policies, and privacy-by-design thinking"}], "description": "Responsible social marketing requires clear boundaries around data collection, targeting, and personalization."}, {"id": "8c7baf7f-9ebd-40e0-88d7-c5accbdb7893", "type": "subtopic", "title": "Accessibility and inclusive design", "children": [{"id": "31b22d20-83e9-4ff0-a818-a2ceebe93c62", "type": "concept", "title": "Alt text, captions, contrast, plain language, flashing content, and screen-reader considerations"}, {"id": "8b571474-5da2-42b1-820d-d9b10cdd6936", "type": "concept", "title": "Inclusive imagery, representation, language, cultural context, and accessibility testing"}, {"id": "c9e79b11-15f4-48bb-a6de-cadff96797c6", "type": "concept", "title": "Avoiding stereotypes, tokenism, exclusionary targeting, and inaccessible trends"}], "description": "Students learn to make social content usable and respectful for broad audiences."}, {"id": "a556bdbf-0ef3-431e-9408-337e684aa0f4", "type": "subtopic", "title": "Platform governance and social responsibility", "children": [{"id": "2afe57e0-bcf5-434f-ae7a-b5608f0271be", "type": "concept", "title": "Algorithmic bias, misinformation, polarization, surveillance, and creator labor"}, {"id": "76a4fb1f-a777-46d2-a393-9f88f07eed29", "type": "concept", "title": "Disclosure, paid partnerships, political content, youth audiences, and harmful persuasion"}, {"id": "ddc275d5-9d1b-4654-b50f-cddd5c78048f", "type": "concept", "title": "Ethical review checklists and professional judgment under pressure"}], "description": "Students examine the larger ethical environment in which social marketers work."}]}, {"id": "b58b82f8-e14e-43f0-a468-73699698b72f", "type": "topic", "title": "Emerging Platforms, Algorithms, AI, and Future Trends", "description": "Students examine how algorithmic feeds, generative AI, creator economies, social search, private communities, and new platforms alter strategy.", "children": [{"id": "e4c48e02-ca51-4d0d-981f-76810a9e18d8", "type": "subtopic", "title": "Algorithmic visibility and social search", "children": [{"id": "7a94787c-a5f9-4c97-8960-9dd694892200", "type": "concept", "title": "Recommendation systems, ranking signals, watch time, engagement, relevance, and freshness"}, {"id": "bf557191-9075-439c-8a1e-9d7b339b0236", "type": "concept", "title": "Social SEO, keywords, captions, metadata, hashtags, and discoverability"}, {"id": "700190e3-f26f-4546-be8d-ca5c807c0958", "type": "concept", "title": "Algorithm changes, volatility, and experimentation"}], "description": "Students learn how discovery is shaped by algorithms and increasingly by search-like behavior inside platforms."}, {"id": "3fc87795-d962-4daa-98f4-41f6815fd7b1", "type": "subtopic", "title": "Generative AI and creative operations", "children": [{"id": "04a72caa-02c6-432e-9223-ab342c6df777", "type": "concept", "title": "AI brainstorming, copy variants, image/video support, social listening, and summarization"}, {"id": "8497b73f-7cc0-40cd-a837-dfe49b3f5a87", "type": "concept", "title": "Disclosure, copyright, bias, deepfakes, synthetic influencers, and authenticity"}, {"id": "7ee20ed7-4fe6-4318-be58-211371b3d844", "type": "concept", "title": "Human review, brand standards, and responsible AI workflow"}], "description": "AI changes ideation, production, personalization, moderation, and analytics, but also creates new risks."}, {"id": "36f9d347-9289-4b9d-a657-7914f4e1c36f", "type": "subtopic", "title": "Future platform trends", "children": [{"id": "c11d3bd8-a9bf-4d12-b2a4-84a6931f238e", "type": "concept", "title": "Private communities, messaging, live shopping, AR, spatial media, decentralized platforms, and creator subscriptions"}, {"id": "df92023d-ca98-4a98-b77e-227b313bc3bf", "type": "concept", "title": "Trend evaluation by audience fit, brand fit, resources, risk, and measurement"}, {"id": "94ddac3d-cfb3-4dfe-ac1f-0eb5eea751d1", "type": "concept", "title": "Pilot design, stop/go criteria, and innovation portfolios"}], "description": "Students develop a habit of evaluating trends without chasing every new tool."}]}, {"id": "9452f8ce-ce42-42dc-91e0-eb9ee567be38", "type": "topic", "title": "Capstone: Integrated Social Media Campaign and Measurement Plan", "description": "The course culminates in a complete social campaign plan with audience research, platform strategy, content, paid media, creator partnerships, measurement, ethics, and executive presentation.", "children": [{"id": "ad870511-6c5e-4dfd-aa7f-7663f83b5ca9", "type": "subtopic", "title": "Campaign strategy and research base", "children": [{"id": "84d8e43d-b355-455b-897a-35cbb7234435", "type": "concept", "title": "Situation analysis, audience research, social listening, persona, and journey map"}, {"id": "2a0fee58-e532-4758-8fdd-d095b044614a", "type": "concept", "title": "Objectives, positioning, message strategy, platform roles, and budget assumptions"}, {"id": "54728f05-2668-4530-a75a-27d80776e7c4", "type": "concept", "title": "Ethics, accessibility, privacy, and brand safety requirements"}], "description": "Students design a campaign grounded in audience insight, platform fit, competitive context, and measurable objectives."}, {"id": "5dfac030-ef62-410c-8440-e72a753f0591", "type": "subtopic", "title": "Creative, community, paid, and creator plan", "children": [{"id": "c339d28f-b12b-4d0e-9259-7a5920aa468b", "type": "concept", "title": "Content pillars, calendar, creative samples, community rules, and response matrix"}, {"id": "66a5997b-2624-42d1-b443-5c0bf21e71e2", "type": "concept", "title": "Paid social plan, targeting, budget, testing structure, and optimization cadence"}, {"id": "c91448ce-16ef-430f-bd07-cb53647491df", "type": "concept", "title": "Creator brief, partner selection, deliverables, disclosure, and rights"}], "description": "The capstone requires a complete plan that can be executed by a real team."}, {"id": "4fe3a32d-d1f2-435a-b234-00b5d1239edc", "type": "subtopic", "title": "Measurement and executive presentation", "children": [{"id": "05e29863-eb9d-4f9c-a38a-80b136316877", "type": "concept", "title": "KPI framework, dashboard, attribution assumptions, and reporting cadence"}, {"id": "0f668a52-ddeb-410d-8074-0ed241f4b216", "type": "concept", "title": "Experiment plan, risks, contingencies, and post-campaign review"}, {"id": "8958dbd5-d440-49d6-b146-9ccec476f8f9", "type": "concept", "title": "Executive presentation, appendix, and portfolio-ready campaign deck"}], "description": "Students finish by presenting a decision-ready plan with clear metrics and learning logic."}]}], "dbBacked": true}$smmkjson$::jsonb,
